def load_modules_with_flags(module_names, flag_values):
    import sys
    import types

    # Save the original flags
    original_flags = {}
    for module_name, flag_value in zip(module_names, flag_values):
        module = sys.modules.get(module_name)
        if module:
            original_flags[module] = module.__dict__.get('__flags__', None)

    # Set the new flags
    for module_name, flag_value in zip(module_names, flag_values):
        module = __import__(module_name)
        module.__dict__['__flags__'] = flag_value

    # Import the modules with the new flags
    imported_modules = [__import__(module_name) for module_name in module_names]

    # Restore the original flags
    for module, original_flag in original_flags.items():
        if original_flag is not None:
            module.__dict__['__flags__'] = original_flag

    return imported_modules
